-- SquadFinder: all migrations + seed in one file, for a FRESH Supabase project.
-- Generated by scripts/build-sql-bundle.mjs from supabase/migrations/*.sql and supabase/seed.sql.
-- Do not edit; change the sources and run `npm run bundle:sql`.
--
-- Safe to run more than once: files that already ran are skipped (see sf_migrations.applied).
-- Existing projects should keep applying the individual files with the Supabase CLI instead.
-- The Supabase dashboard will warn that this script is destructive; it drops and recreates
-- objects it created itself, and never touches data it did not create.

create schema if not exists sf_migrations;
create table if not exists sf_migrations.applied (
  name text primary key,
  applied_at timestamptz not null default now()
);
revoke all on schema sf_migrations from public, anon, authenticated;
revoke all on sf_migrations.applied from public, anon, authenticated;

