-- 20260731000400_convenience_views.sql
-- ---------------------------------------------------------------------------
do $sf_migration$
begin
  if exists (select 1 from sf_migrations.applied where name = '20260731000400_convenience_views.sql') then
    raise notice 'skipping 20260731000400_convenience_views.sql (already applied)';
    return;
