-- 20261101000600_scale_discovery.sql
-- ---------------------------------------------------------------------------
do $sf_migration$
begin
  if exists (select 1 from sf_migrations.applied where name = '20261101000600_scale_discovery.sql') then
    raise notice 'skipping 20261101000600_scale_discovery.sql (already applied)';
    return;
  end if;
